"use client";

import "./preview-card.css";
import { PreviewCard as BasePreviewCard } from "@base-ui/react/preview-card";
import type React from "react";
import { cn } from "tailwind-variants";

import { PreviewCardContext, usePreviewCardContext } from "./preview-card.context";
import { previewCardVariants, type PreviewCardVariants } from "./preview-card.variants";

export type PreviewCardProps = PreviewCardVariants &
  React.ComponentProps<typeof BasePreviewCard.Root>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/preview-card/content.md
 */
export const PreviewCardRoot = ({ children, size, ...props }: PreviewCardProps) => {
  const slots = previewCardVariants({ size });

  return (
    <PreviewCardContext.Provider value={{ slots }}>
      <BasePreviewCard.Root {...props}>{children}</BasePreviewCard.Root>
    </PreviewCardContext.Provider>
  );
};

export type PreviewCardTriggerProps = React.ComponentProps<typeof BasePreviewCard.Trigger>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/preview-card/content.md
 */
export const PreviewCardTrigger = ({ className, ...props }: PreviewCardTriggerProps) => {
  const { slots } = usePreviewCardContext();
  return <BasePreviewCard.Trigger className={cn(slots.trigger(), className)} {...props} />;
};

export type PreviewCardPortalProps = React.ComponentProps<typeof BasePreviewCard.Portal>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/preview-card/content.md
 */
export const PreviewCardPortal = (props: PreviewCardPortalProps) => {
  return <BasePreviewCard.Portal {...props} />;
};

export type PreviewCardBackdropProps = React.ComponentProps<typeof BasePreviewCard.Backdrop>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/preview-card/content.md
 */
export const PreviewCardBackdrop = ({ className, ...props }: PreviewCardBackdropProps) => {
  const { slots } = usePreviewCardContext();
  return <BasePreviewCard.Backdrop className={cn(slots.backdrop(), className)} {...props} />;
};

export type PreviewCardPositionerProps = React.ComponentProps<typeof BasePreviewCard.Positioner>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/preview-card/content.md
 */
export const PreviewCardPositioner = ({
  className,
  sideOffset = 8,
  ...props
}: PreviewCardPositionerProps) => {
  const { slots } = usePreviewCardContext();
  return (
    <BasePreviewCard.Positioner
      className={cn(slots.positioner(), className)}
      sideOffset={sideOffset}
      {...props}
    />
  );
};

export type PreviewCardPopupProps = React.ComponentProps<typeof BasePreviewCard.Popup>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/preview-card/content.md
 */
export const PreviewCardPopup = ({ className, ...props }: PreviewCardPopupProps) => {
  const { slots } = usePreviewCardContext();
  return <BasePreviewCard.Popup className={cn(slots.popup(), className)} {...props} />;
};

export type PreviewCardArrowProps = React.ComponentProps<typeof BasePreviewCard.Arrow>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/preview-card/content.md
 */
export const PreviewCardArrow = ({ className, ...props }: PreviewCardArrowProps) => {
  const { slots } = usePreviewCardContext();
  return <BasePreviewCard.Arrow className={cn(slots.arrow(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const previewCardVariants = tv({
  slots: {
    root: "preview-card",
    trigger: "preview-card__trigger",
    positioner: "preview-card__positioner",
    popup: "preview-card__popup",
    arrow: "preview-card__arrow",
    backdrop: "preview-card__backdrop",
  },
  variants: {
    size: {
      sm: {
        popup: "preview-card__popup--sm",
      },
      md: {
        popup: "preview-card__popup--md",
      },
      lg: {
        popup: "preview-card__popup--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type PreviewCardVariants = VariantProps<typeof previewCardVariants>;

"use client";

import { createContext, useContext } from "react";

import { previewCardVariants } from "./preview-card.variants";

export type PreviewCardContext = {
  slots: ReturnType<typeof previewCardVariants>;
};

export const PreviewCardContext = createContext<PreviewCardContext | null>(null);

export const usePreviewCardContext = () => {
  const context = useContext(PreviewCardContext);
  return context ?? { slots: previewCardVariants() };
};

.preview-card__positioner {
  @apply z-50 outline-none;
}

.preview-card__popup {
  @apply border-border bg-popover text-popover-foreground relative flex max-w-xs flex-col gap-2 rounded-lg border p-3 shadow-md transition-all duration-100 ease-out outline-none data-ending-style:scale-95 data-ending-style:opacity-0 data-starting-style:scale-95 data-starting-style:opacity-0;
}

.preview-card__trigger {
  @apply decoration-muted-foreground/50 hover:decoration-foreground focus-visible:outline-ring cursor-pointer underline underline-offset-2 transition-colors focus-visible:outline-2;
}

.preview-card__arrow {
  @apply fill-popover stroke-border;
}

.preview-card__backdrop {
  @apply fixed inset-0 z-40 bg-black/50 transition-opacity duration-150 data-ending-style:opacity-0 data-starting-style:opacity-0;
}

import { PreviewCard as BasePreviewCard } from "@base-ui/react/preview-card";

import {
  PreviewCardArrow,
  PreviewCardBackdrop,
  PreviewCardPopup,
  PreviewCardPortal,
  PreviewCardPositioner,
  PreviewCardRoot,
  PreviewCardTrigger,
} from "./preview-card";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/preview-card/content.md
 */
export const PreviewCard = {
  Arrow: PreviewCardArrow,
  Backdrop: PreviewCardBackdrop,
  Popup: PreviewCardPopup,
  Portal: PreviewCardPortal,
  Positioner: PreviewCardPositioner,
  Root: PreviewCardRoot,
  Trigger: PreviewCardTrigger,
  createHandle: BasePreviewCard.createHandle,
};

export {
  PreviewCardArrow,
  PreviewCardBackdrop,
  PreviewCardPopup,
  PreviewCardPortal,
  PreviewCardPositioner,
  PreviewCardRoot,
  PreviewCardTrigger,
};

export type {
  PreviewCardArrowProps,
  PreviewCardBackdropProps,
  PreviewCardPopupProps,
  PreviewCardPortalProps,
  PreviewCardPositionerProps,
  PreviewCardProps,
  PreviewCardTriggerProps,
} from "./preview-card";
export { PreviewCardContext, usePreviewCardContext } from "./preview-card.context";
export { type PreviewCardVariants, previewCardVariants } from "./preview-card.variants";
